function rateRecipe(id:string,kind:"yum"|"yuck"|"skip"){update(s=>({...s,likes:kind==="yum"?[...new Set([...(s.likes||[]),id])]:kind==="yuck"?(s.likes||[]).filter(x=>x!==id):s.likes,dislikes:kind==="yuck"?[...new Set([...(s.dislikes||[]),id])]:kind==="yum"?(s.dislikes||[]).filter(x=>x!==id):s.dislikes}));setRatingIndex(i=>i+1)}
